// pet
(() => {
let walker = null;
let last = -1;
let timer = 0;

Deck.use({
  name: "pet-walk",
  enter(slide, deck) {
    if (!deck.config.petWalk) return;
    if (!walker) {
      walker = document.createElement("i");
      walker.className = "pet pet-walk";
      walker.setAttribute("aria-hidden", "true");
      document.body.append(walker);
    }
    const flow = deck.slides().filter(s => !s.classList.contains("is-excluded"));
    const i = flow.indexOf(slide);
    const share = (i + 1) / flow.length;
    walker.style.translate = `max(0px, calc(${share * 100}vw - 100%)) 0`;
    walker.classList.toggle("is-back", i < last);
    if (slide.id === "close") walker.dataset.pose = "wave";
    else delete walker.dataset.pose;
    if (last >= 0 && i !== last && !deck.reducedMotion()) {
      walker.classList.add("is-walking");
      clearTimeout(timer);
      timer = setTimeout(() => walker.classList.remove("is-walking"), 700);
    }
    last = i;
  }
});
})();

// player
(() => {
const parse = v => {
  if (v == null || String(v).trim() === "") return null;
  const parts = String(v).trim().split(":");
  const n = parts.reduce((t, p) => t * 60 + parseFloat(p), 0);
  return Number.isFinite(n) ? n : null;
};
const fmt = (s, round = Math.floor) => {
  s = Math.max(0, round(s));
  return `${Math.floor(s / 60)}:${String(s % 60).padStart(2, "0")}`;
};
const el = (tag, cls, attrs = {}) => Object.assign(document.createElement(tag), { className: cls }, attrs);
const button = (cls, label) => el("button", cls, { type: "button", ariaLabel: label });
const swallow = e => { if (e.name !== "AbortError" && e.name !== "NotAllowedError") console.error(`Video didn't start: ${e.message}`); };
const players = new WeakMap();
const within = root => root.matches(".player") ? [root] : [...root.querySelectorAll(".player")];

function buildVideo(fig, slide) {
  const v = fig.querySelector("video");
  const stage = el("div", "player-stage");
  v.before(stage);
  stage.append(v);
  v.controls = false;

  const start = parse(fig.dataset.start) ?? 0;
  const endAttr = parse(fig.dataset.end);
  const endAt = () => Math.min(endAttr ?? Infinity, Number.isFinite(v.duration) ? v.duration : Infinity);
  const span = () => Number.isFinite(endAt()) ? Math.max(0, endAt() - start) : 0;

  const big = button("player-big", "Play");
  const toggle = button("player-toggle", "Play");
  const seek = el("input", "player-seek", { type: "range", min: "0", max: "0", step: "0.01", value: "0", ariaLabel: "Seek" });
  const time = el("span", "player-time", { textContent: "0:00 / 0:00" });
  const mute = button("player-mute", "Mute");
  stage.append(big, el("div", "player-bar"));
  stage.lastChild.append(toggle, seek, time, mute);

  let started = false;
  let scrubbing = false;
  let raf = 0;

  function paint() {
    const total = span();
    const done = Math.min(Math.max(v.currentTime - start, 0), total);
    const ended = v.paused && started && v.currentTime >= endAt() - 0.05;
    fig.classList.toggle("is-fresh", !started);
    fig.classList.toggle("is-playing", !v.paused);
    fig.classList.toggle("is-ended", ended);
    fig.classList.toggle("is-muted", v.muted);
    toggle.ariaLabel = v.paused ? "Play" : "Pause";
    mute.ariaPressed = String(v.muted);
    time.textContent = `${fmt(done)} / ${fmt(total, Math.round)}`;
    if (scrubbing) return;
    seek.max = String(total);
    seek.value = String(done);
    seek.style.setProperty("--p", total ? `${done / total * 100}%` : "0%");
    seek.ariaValueText = time.textContent;
  }

  function finish() {
    v.pause();
    v.currentTime = endAt();
    paint();
  }

  function tick() {
    raf = 0;
    if (!v.paused && v.currentTime >= endAt() - 0.02) finish();
    paint();
    if (!v.paused) raf = requestAnimationFrame(tick);
  }

  function play() {
    if (v.currentTime >= endAt() - 0.05 || v.currentTime < start - 0.05) v.currentTime = start;
    v.play().catch(swallow);
  }

  const api = {
    play,
    pause: () => v.pause(),
    reset() {
      v.pause();
      started = false;
      v.currentTime = start;
      paint();
    }
  };
  players.set(fig, api);

  v.addEventListener("play", () => { started = true; if (!raf) raf = requestAnimationFrame(tick); paint(); });
  ["pause", "ended", "seeked", "volumechange", "durationchange"].forEach(t => v.addEventListener(t, paint));
  v.addEventListener("loadedmetadata", () => { if (!started) v.currentTime = start; paint(); });
  v.addEventListener("ended", finish);
  v.addEventListener("click", () => v.paused ? play() : v.pause());
  big.addEventListener("click", play);
  toggle.addEventListener("click", () => v.paused ? play() : v.pause());
  mute.addEventListener("click", () => { v.muted = !v.muted; });
  seek.addEventListener("input", () => { v.currentTime = start + Number(seek.value); paint(); });
  seek.addEventListener("pointerdown", () => {
    scrubbing = true;
    addEventListener("pointerup", () => { scrubbing = false; paint(); slide.focus({ preventScroll: true }); }, { once: true });
  });
  paint();
}

function buildYouTube(fig, slide) {
  const id = fig.dataset.youtube;
  const start = Math.floor(parse(fig.dataset.start) ?? 0);
  const stage = fig.querySelector(".player-stage");
  const note = fig.querySelector(".player-note");
  const link = fig.querySelector(".player-link");
  const watch = `https://www.youtube.com/watch?v=${encodeURIComponent(id)}&t=${start}s`;
  const web = () => /^https?:$/.test(location.protocol);
  const embeddable = () => web() && navigator.onLine;
  if (link) link.href = watch;

  function sync() {
    if (!note) return;
    note.textContent = !web() ? "Opens in a new tab: YouTube won’t embed a file opened from disk."
      : !navigator.onLine ? "Offline: this will open YouTube in a new tab." : "";
    note.hidden = !note.textContent;
  }

  function restore() {
    stage.querySelector("iframe")?.remove();
    fig.classList.remove("is-embedded");
  }

  function play() {
    if (!embeddable()) { window.open(watch, "_blank", "noopener"); return; }
    if (stage.querySelector("iframe")) return;
    const frame = el("iframe", "", {
      src: `https://www.youtube-nocookie.com/embed/${encodeURIComponent(id)}?autoplay=1&start=${start}&rel=0`,
      title: fig.querySelector(".player-meta b")?.textContent || "YouTube video player",
      allow: "autoplay; encrypted-media; picture-in-picture; fullscreen",
      allowFullscreen: true,
      referrerPolicy: "strict-origin-when-cross-origin"
    });
    stage.append(frame);
    fig.classList.add("is-embedded");
  }

  fig.querySelector(".player-big")?.addEventListener("click", play);
  addEventListener("online", sync);
  addEventListener("offline", sync);
  sync();
  players.set(fig, { play, pause: restore, reset: restore });
}

Deck.use({
  name: "player",
  init(slide) {
    slide.querySelectorAll(".player").forEach(fig => {
      if (fig.dataset.youtube) buildYouTube(fig, slide);
      else if (fig.querySelector("video")) buildVideo(fig, slide);
      fig.addEventListener("click", e => {
        if (e.detail > 0 && e.target.closest("button, a, video")) slide.focus({ preventScroll: true });
      });
    });
  },
  enter(slide, deck) {
    slide.querySelectorAll(".player").forEach(fig => {
      const p = players.get(fig);
      p?.reset();
      if (p && fig.hasAttribute("data-autoplay") && !fig.dataset.youtube && !deck.reducedMotion() && !fig.closest("[data-step]:not(.is-shown)")) p.play();
    });
  },
  step(els, slide, deck) {
    els.flatMap(within).forEach(fig => {
      if (fig.hasAttribute("data-autoplay") && !fig.dataset.youtube && !deck.reducedMotion()) players.get(fig)?.play();
    });
  },
  unstep(els) {
    els.flatMap(within).forEach(fig => players.get(fig)?.pause());
  },
  leave(slide) {
    slide.querySelectorAll(".player").forEach(fig => players.get(fig)?.reset());
  }
});
})();

// rehearse
(() => {
const rehearsal = { acc: 0, t0: 0, running: false, slideFrom: 0, hud: null, timer: 0, slide: null };

const parseClock = text => {
  const m = String(text || "").trim().match(/^(\d+):(\d{2})$/);
  return m ? (Number(m[1]) * 60 + Number(m[2])) * 1000 : null;
};
const formatClock = ms => {
  const s = Math.max(0, Math.floor(ms / 1000));
  return `${Math.floor(s / 60)}:${String(s % 60).padStart(2, "0")}`;
};
const rehearsalElapsed = () => rehearsal.acc + (rehearsal.running ? performance.now() - rehearsal.t0 : 0);

function plannedWindow(slide) {
  const re = /(\d+:\d{2})\s*[–—-]\s*(\d+:\d{2})/;
  const b = [...(slide?.querySelectorAll("aside.notes b") || [])].find(el => re.test(el.textContent));
  const m = b?.textContent.match(re);
  return m ? { from: parseClock(m[1]), to: parseClock(m[2]), label: `${m[1]}–${m[2]}` } : null;
}

function buildHud() {
  const hud = document.createElement("aside");
  hud.className = "rehearse";
  hud.setAttribute("aria-label", "Rehearsal timer");
  hud.hidden = true;
  hud.innerHTML = `
<div class="rehearse-row"><span class="rehearse-total">0:00</span><span class="rehearse-of"></span><span class="rehearse-status"></span></div>
<div class="rehearse-bar" aria-hidden="true"><i></i></div>
<dl class="rehearse-facts">
  <div><dt>This slide</dt><dd class="rehearse-slide">0:00</dd></div>
  <div><dt>Planned</dt><dd class="rehearse-plan">—</dd></div>
  <div><dt>Slide</dt><dd class="rehearse-count"></dd></div>
</dl>
<p class="rehearse-next"></p>
<div class="rehearse-buttons"><button type="button" class="btn" data-rehearse="toggle">Start</button><button type="button" class="btn" data-rehearse="reset">Reset</button></div>`;
  hud.addEventListener("click", e => {
    const btn = e.target.closest("[data-rehearse]");
    if (!btn) return;
    if (btn.dataset.rehearse === "toggle") setRunning(!rehearsal.running);
    else resetRehearsal();
    Deck.current()?.focus({ preventScroll: true });
  });
  document.body.append(hud);
  return hud;
}

function setRunning(on) {
  if (on === rehearsal.running) return;
  if (on) rehearsal.t0 = performance.now();
  else rehearsal.acc = rehearsalElapsed();
  rehearsal.running = on;
  renderHud();
}

function resetRehearsal() {
  rehearsal.acc = 0;
  rehearsal.t0 = performance.now();
  rehearsal.slideFrom = 0;
  renderHud();
}

function renderHud() {
  const hud = rehearsal.hud;
  if (!hud || hud.hidden) return;
  const q = sel => hud.querySelector(sel);
  const total = rehearsalElapsed();
  const duration = parseClock(Deck.config.duration);
  const plan = plannedWindow(rehearsal.slide);
  const tolerance = 15000;
  let status = "";
  if (duration && total > duration) status = "over";
  else if (plan && total > plan.to + tolerance) status = "behind";
  else if (plan && total < plan.from - tolerance) status = "ahead";
  else if (plan) status = "on time";
  q(".rehearse-total").textContent = formatClock(total);
  q(".rehearse-of").textContent = duration ? `of ${formatClock(duration)}` : "";
  q(".rehearse-status").textContent = status;
  hud.dataset.status = status.replace(" ", "-");
  hud.dataset.running = String(rehearsal.running);
  const bar = q(".rehearse-bar");
  bar.hidden = !duration;
  if (duration) bar.style.setProperty("--p", Math.min(1, total / duration));
  q(".rehearse-slide").textContent = formatClock(total - rehearsal.slideFrom);
  q(".rehearse-plan").textContent = plan ? plan.label : "—";
  const slides = [...document.querySelectorAll("section.slide:not(.is-excluded)")];
  const at = slides.indexOf(rehearsal.slide);
  q(".rehearse-count").textContent = at >= 0 ? `${at + 1} / ${slides.length}` : "extra";
  const next = slides[at + 1];
  q(".rehearse-next").textContent = next ? `Next: ${next.dataset.title || ""}` : "Last slide";
  q('[data-rehearse="toggle"]').textContent = rehearsal.running ? "Pause" : total ? "Resume" : "Start";
}

const rehearseButton = Deck.control({
  label: "Rehearse",
  key: "t",
  pressed: false,
  action() {
    rehearsal.hud ||= buildHud();
    const open = rehearsal.hud.hidden;
    rehearsal.hud.hidden = !open;
    rehearseButton.setAttribute("aria-pressed", String(open));
    clearInterval(rehearsal.timer);
    if (open) {
      rehearsal.slide = Deck.current();
      if (!rehearsalElapsed()) setRunning(true);
      rehearsal.timer = setInterval(renderHud, 250);
      renderHud();
    }
  }
});

Deck.use({
  name: "rehearse",
  enter(slide) {
    rehearsal.slide = slide;
    rehearsal.slideFrom = rehearsalElapsed();
    renderHud();
  }
});
})();

// shot
(() => {
function viewer() {
  let dialog = document.getElementById("image-viewer");
  if (!dialog) {
    document.body.insertAdjacentHTML("beforeend", `<dialog id="image-viewer" class="overlay image-viewer" aria-labelledby="image-viewer-title"><div class="dialog-head"><h2 id="image-viewer-title">Screenshot</h2><button type="button" class="btn" data-close>Close · Esc</button></div><img alt=""><p></p></dialog>`);
    dialog = document.getElementById("image-viewer");
  }
  return dialog;
}

Deck.use({
  name: "shot",
  init(slide, deck) {
    slide.querySelectorAll(".shot img").forEach(img => {
      if (img.parentElement.classList.contains("image-zoom")) return;
      const figure = img.closest(".shot");
      const button = document.createElement("button");
      button.type = "button";
      button.className = "image-zoom";
      button.setAttribute("aria-label", "Enlarge: " + img.alt);
      img.before(button);
      button.append(img);
      button.addEventListener("click", () => {
        const dialog = viewer();
        const large = dialog.querySelector("img");
        large.src = img.currentSrc || img.src;
        large.alt = img.alt;
        dialog.querySelector("p").textContent = figure.querySelector("figcaption")?.textContent || img.alt;
        deck.openDialog(dialog, button);
      });
    });
  }
});
})();

// timer
(() => {
const clock = text => {
  const m = String(text || "").trim().match(/^(\d+):(\d{2})$/);
  return m ? (Number(m[1]) * 60 + Number(m[2])) * 1000 : 300000;
};
const format = ms => {
  const s = Math.ceil(Math.max(0, ms) / 1000);
  return `${Math.floor(s / 60)}:${String(s % 60).padStart(2, "0")}`;
};

function build(slide, el) {
  el.innerHTML = `
<div class="timer-ring"><div class="timer-face"><span class="timer-digits" role="timer"></span><span class="timer-label" aria-live="polite"></span></div></div>
<div class="timer-buttons"><button type="button" class="btn" data-timer="toggle">Start</button><button type="button" class="btn" data-timer="reset">Reset</button><button type="button" class="btn" data-timer="add">+1 min</button></div>`;
  const first = clock(el.dataset.time);
  const t = { el, slide, first, total: first, left: first, running: false, last: 0, id: 0 };
  const digits = el.querySelector(".timer-digits");
  const label = el.querySelector(".timer-label");
  const toggle = el.querySelector('[data-timer="toggle"]');

  const render = () => {
    const done = t.left <= 0;
    el.classList.toggle("is-running", t.running);
    el.classList.toggle("is-done", done);
    el.style.setProperty("--left", (t.left / t.total).toFixed(4));
    digits.textContent = format(t.left);
    label.textContent = done ? "Time’s up" : t.running ? "Running" : t.left < t.total ? "Paused" : "Ready";
    toggle.textContent = t.running ? "Pause" : "Start";
    toggle.disabled = done;
  };
  const tick = () => {
    clearTimeout(t.id);
    const now = performance.now();
    if (t.running) {
      t.left = Math.max(0, t.left - (now - t.last));
      t.last = now;
      if (t.left <= 0) t.running = false;
    }
    render();
    if (t.running) t.id = setTimeout(tick, t.left % 1000 || 1000);
  };
  t.sync = tick;
  t.start = () => {
    if (t.running || t.left <= 0) return;
    t.running = true;
    t.last = performance.now();
    tick();
  };
  t.pause = () => {
    tick();
    t.running = false;
    clearTimeout(t.id);
    render();
  };
  t.reset = () => {
    t.running = false;
    t.total = t.left = t.first;
    clearTimeout(t.id);
    render();
  };
  t.add = () => {
    tick();
    if (t.left <= 0) t.total = 0;
    t.total += 60000;
    t.left += 60000;
    render();
    clearTimeout(t.id);
    if (t.running) t.id = setTimeout(tick, t.left % 1000 || 1000);
  };
  t.pristine = () => !t.running && t.left === t.total && t.total === t.first;

  el.addEventListener("click", e => {
    const btn = e.target.closest("[data-timer]");
    if (!btn) return;
    const action = btn.dataset.timer;
    if (action === "toggle") (t.running ? t.pause : t.start)();
    else t[action]();
    if (e.detail > 0) slide.focus({ preventScroll: true });
  });
  render();
  return t;
}

Deck.use({
  name: "timer",
  init(slide) {
    slide.timers = [...slide.querySelectorAll(".timer")].map(el => build(slide, el));
  },
  enter(slide) {
    (slide.timers || []).forEach(t => {
      if (t.el.hasAttribute("data-autostart") && t.pristine()) t.start();
      else t.sync();
    });
  }
});
})();

// type
(() => {
function typeIn(root, deck) {
  const targets = root.matches?.("[data-type]") ? [root] : root.querySelectorAll("[data-type]");
  targets.forEach(el => {
    const text = el.dataset.type;
    clearTimeout(el._timer);
    el.classList.remove("is-typed");
    if (el.closest("[data-step]:not(.is-shown)")) { el.textContent = ""; return; }
    if (deck.reducedMotion()) { el.textContent = text; el.classList.add("is-typed"); return; }
    el.textContent = "";
    el.classList.add("is-typing");
    let i = 0;
    const step = () => {
      el.textContent = text.slice(0, ++i);
      if (i < text.length) el._timer = setTimeout(step, 26 + Math.random() * 38);
      else { el.classList.remove("is-typing"); el.classList.add("is-typed"); }
    };
    el._timer = setTimeout(step, Number(el.dataset.delay || 700));
  });
}

Deck.use({
  name: "type",
  enter(slide, deck) { typeIn(slide, deck); },
  step(els, slide, deck) { els.forEach(el => typeIn(el, deck)); }
});
})();

// video
(() => {
function play(root, deck) {
  if (deck.reducedMotion()) return;
  root.querySelectorAll(".video video").forEach(v => {
    if (v.closest("[data-step]:not(.is-shown)")) return;
    v.muted = true;
    v.play().catch(e => { if (e.name !== "AbortError") console.error(`Video didn't start: ${e.message}`); });
  });
}

Deck.use({
  name: "video",
  enter(slide, deck) { play(slide, deck); },
  step(els, slide, deck) { els.forEach(el => play(el, deck)); },
  leave(slide) {
    slide.querySelectorAll(".video video").forEach(v => { v.pause(); v.currentTime = 0; });
  }
});
})();

// zoom
(() => {
function update(slide, snap) {
  slide.querySelectorAll(".zoom").forEach(zoom => {
    const items = [...slide.querySelectorAll(".zoom-steps li[data-zoom]")];
    const shown = items.filter(li => li.classList.contains("is-shown"));
    const now = shown[shown.length - 1];
    items.forEach(li => li.classList.toggle("is-current", li === now));
    const [x = 50, y = 50, s = 1] = (now?.dataset.zoom || "").split(/\s+/).map(parseFloat).filter(Number.isFinite);
    if (snap) zoom.classList.add("is-snap");
    zoom.style.setProperty("--zx", x / 100);
    zoom.style.setProperty("--zy", y / 100);
    zoom.style.setProperty("--zs", Math.max(1, s));
    if (snap) {
      zoom.offsetWidth;
      zoom.classList.remove("is-snap");
    }
  });
}

Deck.use({
  name: "zoom",
  init: slide => update(slide, true),
  enter: slide => update(slide, true),
  step: (els, slide) => update(slide),
  unstep: (els, slide) => update(slide)
});
})();
